            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"36\" font-weight=\"bold\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Wood vs. Zinn</text><rect x=\"100\" y=\"150\" width=\"900\" height=\"122\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"204\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"24\" font-weight=\"bold\">The question</text><text x=\"550\" y=\"240\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">How did Gordon Wood see the Revolution?</text><rect x=\"100\" y=\"302\" width=\"900\" height=\"122\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"356\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"24\" font-weight=\"bold\">Hint</text><text x=\"550\" y=\"392\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Look at the title of his 1992 book</text><rect x=\"100\" y=\"454\" width=\"900\" height=\"122\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"508\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"24\" font-weight=\"bold\">The debate</text><text x=\"550\" y=\"544\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Radical change or elite continuity?</text></svg>",
