            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE BARON SPEAKS</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Carnegie on giving it away</text><rect x=\"150\" y=\"200\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">The man who dies thus rich</text><text x=\"550\" y=\"335\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">dies disgraced.</text><rect x=\"80\" y=\"500\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"300\" y=\"560\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">ADMIRERS SEE</text><text x=\"300\" y=\"605\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Libraries, Carnegie Hall,</text><text x=\"300\" y=\"640\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">a duty to give back</text><rect x=\"580\" y=\"500\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"800\" y=\"560\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">ZINN SEES</text><text x=\"800\" y=\"605\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Homestead three years later,</text><text x=\"800\" y=\"640\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">charity on his own terms</text></svg>",
