            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">DEBS AT SENTENCING</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Cleveland, September 1918</text><rect x=\"120\" y=\"200\" width=\"860\" height=\"360\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">While there is a lower class,</text><text x=\"550\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">I am in it ... while there is</text><text x=\"550\" y=\"380\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">a criminal element I am of it ...</text><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">while there is a soul in prison,</text><text x=\"550\" y=\"480\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">I am not free.</text><rect x=\"150\" y=\"660\" width=\"800\" height=\"100\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"720\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Sentenced to ten years under the Espionage Act</text></svg>",
